// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint128 amountA, uint128 amountB, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 a = bound(uint256(amountA), 0, 1 ether);
        uint256 b = bound(uint256(amountB), 0, 1 ether);
        vm.assume(a + b > 0);

        vm.deal(actor, a + b);
        vm.prank(actor);
        c.Put{value: a}(0);
        vm.prank(actor);
        c.Put{value: b}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == a + b);
    }
}
